import { useState } from "react";
import { ClipboardIcon, EyeIcon, EyeSlashIcon, GlobeAltIcon, KeyIcon, LinkIcon, PencilSquareIcon, ServerIcon, ShieldCheckIcon, TrashIcon, UserIcon } from "@heroicons/react/24/outline";
import type { ExtendedMikrotikConnection } from "../types/mikrotikConnections";
interface Props { connections: ExtendedMikrotikConnection[]; loading: boolean; copiedKey: string | null; onCopy: (id: string, field: string, value: string) => void; onEdit: (connection: ExtendedMikrotikConnection) => void; onDelete: (id: string) => void; }
function CopyButton({ copied, label, onClick }: { copied: boolean; label: string; onClick: () => void }) { return <button type="button" onClick={onClick} title={`Copy ${label}`} aria-label={`Copy ${label}`} className="rounded-md p-1 text-slate-400 transition hover:bg-sky-50 hover:text-sky-700 dark:hover:bg-slate-700 dark:hover:text-sky-300">{copied ? <span className="text-[10px] font-bold text-emerald-600">Copied</span> : <ClipboardIcon className="h-3.5 w-3.5" />}</button>; }
export default function ConnectionsTable({ connections, loading, copiedKey, onCopy, onEdit, onDelete }: Props) {
  const [visibleCredentials, setVisibleCredentials] = useState<Record<string, boolean>>({});
  if (loading && connections.length === 0) return <div className="rounded-2xl border border-slate-200 bg-white p-10 text-center text-sm text-slate-500 dark:border-slate-700 dark:bg-gray-800 dark:text-slate-400">Loading MikroTik connections...</div>;
  return <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-700 dark:bg-gray-800"><div className="flex items-center justify-between gap-3 border-b border-slate-100 px-4 py-3 dark:border-slate-700 sm:px-5"><div><h2 className="text-sm font-bold text-slate-900 dark:text-white">Configured connections</h2><p className="mt-0.5 text-xs text-slate-500 dark:text-slate-400">{connections.length} connection{connections.length === 1 ? "" : "s"}</p></div>{loading && <span className="text-xs text-sky-600 dark:text-sky-400">Refreshing…</span>}</div>
  {!connections.length ? <div className="px-5 py-14 text-center"><div className="mx-auto flex h-12 w-12 items-center justify-center rounded-2xl bg-gradient-to-br from-sky-100 to-emerald-100 text-sky-700 dark:from-sky-950 dark:to-emerald-950 dark:text-sky-300"><ServerIcon className="h-6 w-6" /></div><p className="mt-3 text-sm font-semibold text-slate-700 dark:text-slate-200">No connections found</p><p className="mt-1 text-xs text-slate-500 dark:text-slate-400">Add a connection or adjust your search.</p></div> : <div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left"><thead className="bg-slate-50/80 dark:bg-gray-900/60"><tr>{["Router", "Network endpoint", "Credentials", "Hotspot URL", "Security", "Actions"].map(h => <th key={h} className="px-4 py-3 text-[10px] font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400 sm:px-5">{h}</th>)}</tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-700">{connections.map(c => <tr key={c.id || String(c.mikrotik)} className="transition hover:bg-sky-50/40 dark:hover:bg-slate-900/40">
  <td className="px-4 py-4 sm:px-5"><div className="flex items-center gap-3"><span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-sky-50 text-sky-700 dark:bg-sky-950 dark:text-sky-300"><ServerIcon className="h-4 w-4" /></span><div><p className="text-sm font-semibold text-slate-800 dark:text-slate-100">{c.mikrotik}</p><p className="mt-0.5 text-[11px] text-slate-500 dark:text-slate-400">{c.enabled ? "Enabled" : "Disabled"}</p></div></div></td>
  <td className="px-4 py-4 sm:px-5"><p className="font-mono text-xs font-semibold text-slate-700 dark:text-slate-200">{c.management_ip}</p><p className="mt-1 text-[11px] text-slate-500 dark:text-slate-400">Port {c.port}</p></td>
  <td className="px-4 py-4 sm:px-5"><div className="space-y-2"><div className="flex items-center gap-1.5"><UserIcon className="h-3.5 w-3.5 text-sky-600 dark:text-sky-400" /><span className="max-w-36 truncate text-xs font-semibold text-slate-700 dark:text-slate-200">{c.username || "—"}</span>{c.username && <CopyButton copied={copiedKey === `${c.id}-username`} label="username" onClick={() => onCopy(c.id, "username", c.username)} />}</div><div className="flex items-center gap-1.5"><KeyIcon className="h-3.5 w-3.5 text-emerald-600 dark:text-emerald-400" /><span className="font-mono text-xs text-slate-500 dark:text-slate-400">{visibleCredentials[c.id] && c.password ? c.password : "••••••••"}</span><button type="button" onClick={() => setVisibleCredentials(p => ({ ...p, [c.id]: !p[c.id] }))} aria-label={visibleCredentials[c.id] ? "Hide password" : "Show password"} className="rounded p-1 text-slate-400 hover:text-sky-600">{visibleCredentials[c.id] ? <EyeSlashIcon className="h-3.5 w-3.5" /> : <EyeIcon className="h-3.5 w-3.5" />}</button>{c.password && <CopyButton copied={copiedKey === `${c.id}-password`} label="password" onClick={() => onCopy(c.id, "password", c.password!)} />}</div></div></td>
  <td className="px-4 py-4 sm:px-5"><div className="flex items-center gap-1.5"><LinkIcon className="h-3.5 w-3.5 shrink-0 text-slate-400" /><span className="max-w-40 truncate font-mono text-xs text-slate-500 dark:text-slate-400">{c.hotspot_login_url || "—"}</span>{c.hotspot_login_url && <CopyButton copied={copiedKey === `${c.id}-url`} label="hotspot URL" onClick={() => onCopy(c.id, "url", c.hotspot_login_url!)} />}</div></td>
  <td className="px-4 py-4 sm:px-5">{c.use_ssl ? <span className="inline-flex items-center gap-1.5 rounded-full border border-emerald-200 bg-emerald-50 px-2.5 py-1.5 text-[10px] font-semibold text-emerald-700 dark:border-emerald-900 dark:bg-emerald-950/50 dark:text-emerald-300"><ShieldCheckIcon className="h-3.5 w-3.5" />SSL</span> : <span className="inline-flex items-center gap-1.5 rounded-full border border-sky-200 bg-sky-50 px-2.5 py-1.5 text-[10px] font-semibold text-sky-700 dark:border-sky-900 dark:bg-sky-950/50 dark:text-sky-300"><GlobeAltIcon className="h-3.5 w-3.5" />Standard</span>}</td>
  <td className="px-4 py-4 text-right sm:px-5"><div className="flex justify-end gap-1"><button type="button" onClick={() => onEdit(c)} title="Edit connection" className="rounded-lg p-2 text-slate-400 transition hover:bg-sky-50 hover:text-sky-700 dark:hover:bg-slate-700 dark:hover:text-sky-300"><PencilSquareIcon className="h-4 w-4" /></button><button type="button" onClick={() => onDelete(c.id)} title="Delete connection" className="rounded-lg p-2 text-slate-400 transition hover:bg-rose-50 hover:text-rose-600 dark:hover:bg-rose-950/40 dark:hover:text-rose-300"><TrashIcon className="h-4 w-4" /></button></div></td>
  </tr>)}</tbody></table></div>}</section>;
}
